

local System = _G.System

local Metatable = {
    __index = function(mytable, key)
        return function(...)
            local value = mytable.item
            if mytable.isnil then
                value = nil
            end
            if key=="get" then
                if typeof(value) == "string" then
                    return System.String.get(value,select(2,...))
                end
                if value.get==nil then
                    local v1=select(2,...)
                    if type(v1)=="number" then
                        return value[v1+1]
                    else
                        return value[v1]
                    end
                end
                return value:get(select(2,...))
            end
            if key=="ToString"  then
                return System.toString2(value,select(2,...))
            end
            return System.Object2[key](value,select(2,...))
        end
      end
}

-- 将 Object 包一层
System.O = function(x)
    local t={
        item=x,
        isnil = x==nil
    }
    setmetatable(t,Metatable)
    return t
end


System.Object2= {
    EqualsObj = System.Object.EqualsObj,
    ReferenceEquals = System.Object.ReferenceEquals,
    GetHashCode = function(this)
        local type = typeof(this)
        if type=="table" then
            local t = this["GetHashCode"]
            if t~=nil then
                return t(this)
            end
        end
        return System.Object.GetHashCode(this)
    end,
    EqualsStatic = System.Object.EqualsStatic,
    GetType = System.ObjectGetType,
    ToString = function(this)
        local type = typeof(this)
        if type=="table" then
            local t = this["ToString"]
            if t~=nil then
                return t(this)
            end
        end
        return System.Object.ToString(this)
      end,
      CompareTo = function(this,other)
        local type = typeof(this)
        if type=="table" then
            local t = this["CompareTo"]
            if t~=nil then
                return t(this,other)
            end
        end
        return System.compareObj(this,other)
      end,
  }


return {i=1}